    species[3] = +3.298677000000000e+00 + 1.408240400000000e-03 * T -
                 3.963222000000000e-06 * T2 + 5.641515000000000e-09 * T3 -
                 2.444854000000000e-12 * T4;
    // species 5: O
    species[5] = +3.168267100000000e+00 - 3.279318840000000e-03 * T +
                 6.643063960000000e-06 * T2 - 6.128066240000000e-09 * T3 +
                 2.112659710000000e-12 * T4;
    // species 6: OH
    species[6] = +4.125305610000000e+00 - 3.225449390000000e-03 * T +
                 6.527646910000000e-06 * T2 - 5.798536430000000e-09 * T3 +
                 2.062373790000000e-12 * T4;
    // species 7: HCO
    species[7] = +4.221185840000000e+00 - 3.243925320000000e-03 * T +
                 1.377994460000000e-05 * T2 - 1.331440930000000e-08 * T3 +
                 4.337688650000000e-12 * T4;
