    species[8] = +4.301798010000000e+00 - 4.749120510000000e-03 * T +
                 2.115828910000000e-05 * T2 - 2.427638940000000e-08 * T3 +
                 9.292251240000000e-12 * T4;
    // species 9: H2O
    species[9] = +4.198640560000000e+00 - 2.036434100000000e-03 * T +
                 6.520402110000000e-06 * T2 - 5.487970620000000e-09 * T3 +
                 1.771978170000000e-12 * T4;
    // species 10: CO
    species[10] = +3.579533470000000e+00 - 6.103536800000000e-04 * T +
                  1.016814330000000e-06 * T2 + 9.070058840000000e-10 * T3 -
                  9.044244990000000e-13 * T4;
    // species 11: O2
    species[11] = +3.782456360000000e+00 - 2.996734160000000e-03 * T +
                  9.847302010000000e-06 * T2 - 9.681295090000001e-09 * T3 +
                  3.243728370000000e-12 * T4;
    // species 12: H2O2
    species[12] = +4.276112690000000e+00 - 5.428224169999999e-04 * T +
                  1.673357010000000e-05 * T2 - 2.157708130000000e-08 * T3 +
                  8.624543630000000e-12 * T4;
