              (+4.276112690000000e+00 - 2.714112085000000e-04 * T +
               5.577856700000000e-06 * T2 - 5.394270325000000e-09 * T3 +
               1.724908726000000e-12 * T4 - 1.770258210000000e+04 * invT) *
              0.0293996589639560;
    // species 13: CO2
    result += y[13] *
              (+2.356773520000000e+00 + 4.492298385000000e-03 * T -
               2.374520896666666e-06 * T2 + 6.147975550000000e-10 * T3 -
               2.873990960000000e-14 * T4 - 4.837196970000000e+04 * invT) *
              0.0227226249176305;
