              (+3.337279200000000e+00 - 2.470123655000000e-05 * T +
               1.664855926666667e-07 * T2 - 4.489159850000000e-11 * T3 +
               4.005107520000000e-15 * T4 - 9.501589220000000e+02 * invT) *
              0.4960317460317460;
    // species 1: H
