              (+2.500000010000000e+00 - 1.154214865000000e-11 * T +
               5.385398266666667e-15 * T2 - 1.183788087500000e-18 * T3 +
               9.963947140000001e-23 * T4 + 2.547365990000000e+04 * invT) *
              0.9920634920634921;
    // species 3: N2
